/// <summary>
/// MPJ_22903_SalesOrderGuide
/// Handles execution of sales order guides (applying checks and updates to orders
/// based on applicable guide).
/// </summary>
class METSalesOrderGuideExecution
{
    // Params
    SalesId                     salesID;

    // State
    METCustParameters           metCustParams;
    SalesTable                  salesTable;
    SalesLine                   salesLine;
    InventTable                 inventTable;
    METSalesOrderGuideTable     orderGuide;

}

Method.Source:
    public boolean run()
    {
        salesTable = SalesTable::find(salesId);
        if(!salesTable)
            throw error(strFmt("@MET:SalesOrderNotFound", salesId));

        metCustParams = METCustParameters::find();

        METSalesOrderGuideID guideID = METSalesOrderGuideExecution::determineSalesOrderGuide(salesTable);
        if(guideID)
        {
            orderGuide = METSalesOrderGuideTable::findThrow(guideID);

            ttsbegin;
       
            METSalesLine metSalesLine;

            while select forupdate salesLine
                where   salesLine.SalesId       == salesTable.SalesId
            join forupdate metSalesLine
                where   metSalesLine.SalesLine  == salesLine.RecId
            join inventTable
                where   inventTable.ItemId      == salesLine.ItemId
            {
                if(!this.checkLine())
                {
                    salesLine.RemainInventPhysical  = 0;
                    salesLine.RemainInventFinancial = 0;
                    salesLine.RemainSalesPhysical   = 0;
                    salesLine.RemainSalesFinancial  = 0;

                    if(metCustParams.OrderGuideNotInRangeReasonId)
                    {
                        metSalesLine.ReasonID = metCustParams.OrderGuideNotInRangeReasonId;
                        metSalesLine.update();
                    }
                    salesLine.update();

                    warning(strFmt("@MET:SalesOrderGuideItemRemovedWarning",
                        salesLine.ItemId,
                        orderGuide.SalesOrderGuideID,
                        orderGuide.Description));
                }
            }

            ttscommit;
        }
        return true;
    }

    protected boolean checkLine()
    {     
        boolean checkPublishedItemList = false;  // ** See note in checkLinePublishedItemList.
        boolean inclusionFound, exclusionFound;

        if(checkPublishedItemList)
        {
            return this.checkLinePublishedItemList();
        }
        else
        {
            METSalesOrderGuideLine  guideLine;

            // Check item-specific guide lines
            while select guideLine
                where   guideLine.SalesOrderGuideID == orderGuide.SalesOrderGuideID
                &&      guideLine.LineType          == METSalesOrderGuideLineType::Item
                &&      guideLine.ItemId            == salesLine.ItemId
                &&      guideLine.AttributeName     == ''
                &&      guideLine.AttributeValue    == ''
            {
                if(guideLine.IncludeExclude == METSalesOrderGuideInclusion::Include)
                {
                    // Specific inclusion for item.
                    inclusionFound = true;
                }
                else
                {
                    // Specific exclusion for item.
                    exclusionFound = true;
                }
            }

            // Check attribute-based guide lines
            while select guideLine
                order by guideLine.IncludeExclude
                where   guideLine.SalesOrderGuideID == orderGuide.SalesOrderGuideID
                &&      guideLine.LineType          == METSalesOrderGuideLineType::Attribute
                &&      guideLine.ItemId            == ''
                &&      guideLine.AttributeName     != ''
                &&      guideLine.AttributeValue    != ''
            {
                METEcoResProductAttributeValueExpanded productAttributeValue;
                select firstonly productAttributeValue
                    where   productAttributeValue.Product           == inventTable.Product
                    &&      productAttributeValue.AttributeName     == guideLine.AttributeName
                    &&      productAttributeValue.TextValue         == guideLine.AttributeValue
                    &&      productAttributeValue.ItemDataAreaId    == curExt();
                if(productAttributeValue)
                {
                    if(guideLine.IncludeExclude == METSalesOrderGuideInclusion::Include)
                    {
                        // Item has an included attribute value
                        inclusionFound = true;
                    }
                    else
                    {
                        // Item has an excluded attribute value
                        exclusionFound = true;
                    }
                }
            }
            if(inclusionFound)
            {
                return !exclusionFound;
            }
            return false;
        }
    }

/// <summary>
/// Check line via pre-expanded / published list of items.
/// TODO once all requirements clarified, this will be the preferred way
/// to check during SO processing.
/// See METSalesOrderGuidePublish
/// </summary>
/// <returns></returns>
protected boolean checkLinePublishedItemList()
{
    METSalesOrderGuideExpanded itemList;
    select firstonly RecId from itemList
        where   itemList.SalesOrderGuideID  == orderGuide.SalesOrderGuideID
        &&      itemList.ItemId             == salesLine.ItemId;
    return itemList.RecId != 0;
}

public SalesID parmSalesID(SalesId _salesID = salesID)
{
    salesID = _salesID;
    return salesID;
}

    /// <summary>
    /// Determine sales order guide applicable to the specified sales order.
    /// </summary>
    /// <param name = "_salesTable">_salesTable</param>
    /// <returns>Order guide ID, or blank if none found</returns>
    static public METSalesOrderGuideID determineSalesOrderGuide(SalesTable _salesTable)
    {
        METSalesOrderGuideID    guideID;
        METCustTable            metCust;
        
        metCust = METCustTable::find(_salesTable.CustAccount);
        if(metCust.SalesOrderGuideID)
        {
            guideID = metCust.SalesOrderGuideID;
        }
        else
        {
            // TODO Check "Customer operations group pricing attributes". Pending dev?
            if(metCust.CustOperGroupId)
            {
                METCustOperGroup operGroup = METCustOperGroup::find(metCust.CustOperGroupId);
                if(operGroup.SalesOrderGuideID)
                {
                    guideID = operGroup.SalesOrderGuideID;
                }
            }
        }
        if(guideID)
        {
            METSalesOrderGuideTable guide = METSalesOrderGuideTable::find(guideID);
            if(!guide)
            {
                warning(strFmt("@MET:SalesOrderGuideSpecifiedDoesNotExist",
                    guideID,
                    _salesTable.SalesId,
                    _salesTable.CustAccount,
                    _salesTable.custTable_CustAccount()));
                guideID = '';

            }
            else
            {
                if(guide.Status != METSalesOrderGuideStatus::Active)
                {
                    warning(strFmt("@MET:SalesOrderGuideSpecifiedInvalidStatus",
                        guideID,
                        _salesTable.SalesId,
                        _salesTable.CustAccount,
                        _salesTable.custTable_CustAccount(),
                        guide.Status));
                    guideID = '';
                }
                else
                {
                    if(!guide.isActiveForDate())
                    {
                        warning(strFmt("@MET:SalesOrderGuideSpecifiedInvalidDate",
                            guideID,
                            _salesTable.SalesId,
                            _salesTable.CustAccount,
                            _salesTable.custTable_CustAccount()));                        
                        guideID = '';
                    }
                }
            }
        }
        return guideID;
    }

/// <summary>
/// Apply order guide checks to specified order.
/// </summary>
/// <param name = "_salesID">Sales order</param>
/// <returns></returns>
static boolean applyChecksToOrder(SalesId _salesID)
{
    METSalesOrderGuideExecution exec = new METSalesOrderGuideExecution();
    exec.parmSalesID(_salesID);
    return exec.run();
}

    /// <summary>
    /// main
    /// </summary>
    /// <param name = "_args">_args</param>
    static public void main(Args _args)
    {
        SalesTable salesTable = _args.record();
        if(!salesTable)
        {
            throw error(error::missingRecord(funcName()));
        }
        if(Box::yesNo(strFmt("@MET:SalesOrderGuideApplyPrompt", salesTable.SalesId), DialogButton::No) != DialogButton::Yes)
        {
            throw Exception::Break;
        }

        METSalesOrderGuideExecution::applyChecksToOrder(salesTable.SalesId);

        if(FormDataUtil::getFormDataSource(salesTable))
        {
            FormDataUtil::getFormDataSource(salesTable).research(true);
        }
    }
